"""Fetch catalogued media using a fresh request generated by the vendor wizard."""
import os
from pathlib import Path
import re
import subprocess
import time
import urllib.error
import urllib.parse
import urllib.request
import xml.etree.ElementTree as ET

from .credentials import read_log


def toolbox_packages(catalog):
    result = []
    for node in ET.parse(catalog).findall('.//DownloadFile'):
        name = node.findtext('FileName', '')
        if not name.lower().startswith('toolbox_'):
            continue
        if not re.fullmatch(r'Toolbox_[a-z_]+\.exe', name, re.I):
            raise ValueError('Unsafe package filename in catalog')
        domain = node.findtext('Domain')
        server = node.findtext('ServerPath', '')
        if domain != 'dl-ak.solidworks.com' or not server.startswith('secured/sw2026/'):
            raise ValueError('Unexpected download origin in catalog')
        if '..' in server.split('/'):
            raise ValueError('Unsafe server path in catalog')
        result.append(dict(name=name, domain=domain, server=server,
                           size=int(node.findtext('FileSizeBytes')),
                           crc=int(node.findtext('CheckSum32'))))
    if not result:
        raise ValueError('No Toolbox packages in vendor catalog')
    return result


def request_template(log):
    requests = re.findall(r'https?://im\.solidworks\.com/2026/GetDownloadURL\.aspx\?[^\s]+', read_log(log))
    if not requests:
        raise ValueError('No vendor-generated download request; start Download Now in the wizard first')
    return urllib.parse.urlsplit(requests[-1])


def authorized_url(template, package):
    changes = dict(filename=package['name'], domain=package['domain'], subpath=package['server'])
    query = [(key, changes.get(key, value)) for key, value in urllib.parse.parse_qsl(template.query)]
    return urllib.parse.urlunsplit(template._replace(scheme='https', query=urllib.parse.urlencode(query)))


class VendorRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        parts = urllib.parse.urlsplit(newurl)
        if parts.hostname not in ('im.solidworks.com', 'im-ak.solidworks.com', 'dl-ak.solidworks.com'):
            raise ValueError('Download redirected outside expected vendor hosts')
        newurl = urllib.parse.urlunsplit(parts._replace(scheme='https'))
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def check_package(path, package):
    if not path.is_file() or path.stat().st_size != package['size']:
        return False
    helper = Path(__file__).resolve().parents[2] / 'build/solidworks-checksum'
    result = subprocess.run([str(helper), str(path)], check=True, capture_output=True,
                            text=True, timeout=60)
    return int(result.stdout.strip()) == package['crc']


def download_package(template, package, destination, timeout=180):
    path = destination / package['name']
    if check_package(path, package):
        print(f"Verified cached {package['name']}", flush=True)
        return path
    if path.exists():
        raise ValueError(f"Existing package fails validation: {path.name}; preserved for inspection")
    partial = path.with_suffix('.exe.part')
    if partial.exists():
        if not check_package(partial, package):
            raise ValueError(f'Previous partial failed validation: {partial.name}; preserved for inspection')
        os.link(partial, path)
        partial.unlink()
        print(f"Verified completed partial {package['name']}", flush=True)
        return path
    # Never clobber a previous partial or another downloader's work.
    start = time.monotonic()
    opener = urllib.request.build_opener(VendorRedirect())
    request = urllib.request.Request(authorized_url(template, package), headers={'User-Agent': 'sldIM'})
    size = 0
    try:
        with opener.open(request, timeout=30) as response, partial.open('xb') as output:
            while chunk := response.read(1024 * 1024):
                size += len(chunk)
                if size > package['size'] or time.monotonic() - start > timeout:
                    raise ValueError('Download exceeded catalog size or time limit')
                output.write(chunk)
        if size != package['size'] or not check_package(partial, package):
            raise ValueError(f"Package size/checksum mismatch: {package['name']}")
        # Exclusive link avoids overwriting a file created since our initial check.
        os.link(partial, path)
        partial.unlink()
        print(f"Verified {package['name']}: {size} bytes, vendor CheckSum32 {package['crc']}", flush=True)
        return path
    except urllib.error.HTTPError as exc:
        raise ValueError(f"Vendor returned HTTP {exc.code} for {package['name']}; refresh the wizard session if expired") from None
    except urllib.error.URLError:
        raise ValueError(f"Network failure for {package['name']}; any partial file was preserved") from None
